59	func (k *KubectlCmd) filterAPIResources(config *rest.Config, preferred bool, resourceFilter ResourceFilter, filter filterFunc) ([]APIResourceInfo, error) {
60		disco, err := discovery.NewDiscoveryClientForConfig(config)
61		if err != nil {
62			return nil, fmt.Errorf("failed to create discovery client: %w", err)
63		}
64	
65		var serverResources []*metav1.APIResourceList
66		if preferred {
67			serverResources, err = disco.ServerPreferredResources()
68		} else {
69			_, serverResources, err = disco.ServerGroupsAndResources()
70		}
71	
72		if err != nil {
73			if len(serverResources) == 0 {
74				return nil, fmt.Errorf("failed to discover server resources, zero resources returned: %w", err)
75			}
76			k.Log.Error(err, "Partial success when performing preferred resource discovery")
77		}
78		apiResIfs := make([]APIResourceInfo, 0)
79		for _, apiResourcesList := range serverResources {
80			gv, err := schema.ParseGroupVersion(apiResourcesList.GroupVersion)
81			if err != nil {
82				gv = schema.GroupVersion{}
83			}
84			for _, apiResource := range apiResourcesList.APIResources {
85				if resourceFilter.IsExcludedResource(gv.Group, apiResource.Kind, config.Host) {
86					continue
87				}
88	
89				if filter(&apiResource) {
90					resource := ToGroupVersionResource(apiResourcesList.GroupVersion, &apiResource)
91					gv, err := schema.ParseGroupVersion(apiResourcesList.GroupVersion)
92					if err != nil {
93						return nil, fmt.Errorf("failed to parse group version %q: %w", apiResourcesList.GroupVersion, err)
94					}
95					apiResIf := APIResourceInfo{
96						GroupKind:            schema.GroupKind{Group: gv.Group, Kind: apiResource.Kind},
97						Meta:                 apiResource,
98						GroupVersionResource: resource,
99					}
100					apiResIfs = append(apiResIfs, apiResIf)
101				}
102			}
103		}
104		return apiResIfs, nil
105	}
